head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDINS11000.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
    fn_CtrlBtn("no_data");
    scwin.ins_Search();
};


/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {
    ins_combo_set(dts_STD_CD_APPL_CONTN_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03425", "ALL"); // 상품구분
    ins_combo_set(dts_APPL_PROCS_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03398", "ALL"); // 처리구분
    //dts_APPL_PROCS_TP_CD 필터링.(변경처리를 삭제하자.)
    var nRow = $c.cp.getNameValueRow(dts_APPL_PROCS_TP_CD, "VALUE", "1");
    $c.cp.removeRow(dts_APPL_PROCS_TP_CD, nRow);
};


/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FROM_STD_CD_APPL_DD.setValue(vCurDate);
    //	edt_FROM_STD_CD_APPL_DD.Text = vCurDate.substr(0, 6) + "01";	
    edt_TO_STD_CD_APPL_DD.setValue(vCurDate);
    var array_grid = [grd_ApplInfo];
    setResizeGrid(array_grid);
};



/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_ApplInfo.removeAll();
    txb_TotalCnt.setValue("총 0건");
};


/**
 * 삭제신청목록조회
 */
scwin.ins_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid("ins_Search")) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_ApplInfo);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listStdCdInfoInquiry" + "&outputMessageId=INS_LIST_STD_CD_INFO_INQUIRY" + "&param01=" + $c.stf.getObjectValue(edt_FROM_STD_CD_APPL_DD) + "&param02=" + $c.stf.getObjectValue(edt_TO_STD_CD_APPL_DD) + "&param03=" + $c.stf.getObjectValue(cmb_STD_CD_APPL_CONTN_TP_CD) + "&param04=" + $c.stf.getObjectValue(cmb_APPL_PROCS_TP_CD) + "&param05=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&param06=" + $c.stf.getObjectValue(txb_ISU_NM);
    dts_ApplInfo.DataID = encodeURI(url);
    dts_ApplInfo.Reset();
};


/**
 * 표준코드 삭제
 */
scwin.ins_Delete = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("ins_Delete")) {
        return;
    }
    var tmpMsg = "삭제시 관련기관의 데이터도 삭제되니 주의하시기 바랍니다.\n\n삭제 처리 하시겠습니까?";
    if (!confirm(tmpMsg)) {
        return;
    }

    // 선택된 Row만 서버로 전송..
    scwin.fn_SetTransData();
    trs_Delete.Action = "/StdCdInfoListAction.do?method=removeStdCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_Delete.KeyName = "toinb_dataid4";
    trs_Delete.KeyValue = "JSP(I:pInput=dts_ApplInfo)";
    trs_Delete.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_Delete.Post();
};


/**
 * 반송처리
 */
scwin.ins_Ret = function() {
    // 사전체크
    if (!scwin.fn_ChkValid("ins_Ret")) {
        return;
    }
    var tmpMsg = "반송처리 하시겠습니까?";
    if (!confirm(tmpMsg)) {
        return;
    }

    // 선택된 Row만 서버로 전송..
    scwin.fn_SetTransData();
    trs_Ret.Action = "/StdCdInfoListAction.do?method=returnStdCdInfo" + "&SCREN_ID=" + scwin.vScrenID + "&queryId=lds.ins.stdcd.update.returnStdCdInfo1" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_Ret.KeyName = "toinb_dataid4";
    trs_Ret.KeyValue = "JSP(I:pInput=dts_ApplInfo)";
    trs_Ret.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_Ret.Post();
};


/**
 * 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 */
scwin.fn_SetTransData = function() {
    var nRow = dts_ApplInfo.getRowPosition();
    dts_ApplInfo.setCellData(nRow, "CHK", "T");
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function(pGubun) {
    if (pGubun == undefined) {
        return true;
    }
    if (pGubun == "ins_Search") {
        if ($c.stf.getObjectValue(edt_FROM_STD_CD_APPL_DD) == "") {
            $c.win.alert("신청시작일자를 입력하세요.");
            edt_FROM_STD_CD_APPL_DD.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_TO_STD_CD_APPL_DD) == "") {
            $c.win.alert("신청종료일자를 입력하세요.");
            edt_TO_STD_CD_APPL_DD.focus();
            return false;
        }
        if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_APPL_DD, edt_TO_STD_CD_APPL_DD) == false) {
            return false;
        }
    } else if (pGubun == "ins_Delete") {
        if (!fn_checkSendTime(dts_time, scwin.vScrenID)) {
            $c.win.alert("정보문의 전송 마감시간(19:00)이 초과되어 삭제하실수 없습니다.");
            return false;
        }
        // 스트립인경우.
        if (dts_ApplInfo.getCellData(dts_ApplInfo.getRowPosition(), "STD_CD_APPL_CONTN_TP_CD") == "8") {
            $c.win.alert("시스템 담당자에게 연락바랍니다.");
            return false;
        }
    }
    return true;
};


/**
 * 발생기관 팝업에서 값 받음.
 */
scwin.fn_GetParam = function(arrPar) {
    arrPar[0] = txb_param1.getValue();
    arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.img_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_ISUR_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.dts_ApplInfo_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_ApplInfo);
    $c.stf.alert_error(dts_ApplInfo);
};
scwin.dts_ApplInfo_OnLoadCompleted = function(rowcount) {
    if (dts_ApplInfo.errorMsg) {
        $c.win.alert(dts_ApplInfo.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_ApplInfo);
    txb_TotalCnt.setValue("총 " + rowcount + "건");

    // 데이터가 없는 경우
    if (rowcount == 0) {
        fn_CtrlBtn("no_data");
    } else {
        fn_CtrlBtn("update");
    }
};
scwin.dts_ApplInfo_OnRowPosChanged = function(row) {
    // 미처리 인경우만 버튼 활성.
    if (row > 0 && dts_ApplInfo.getCellData(row, "APPL_PROCS_TP_CD") == "0") {
        fn_CtrlBtn("update");
    } else {
        fn_CtrlBtn("no_data");
    }
};
scwin.img_FROM_STD_CD_APPL_DD_onclick = function() {
    popUpCalendar2(edt_FROM_STD_CD_APPL_DD);
};
scwin.img_TO_STD_CD_APPL_DD_onclick = function() {
    popUpCalendar2(edt_TO_STD_CD_APPL_DD);
};
scwin.btn_search_onclick = function() {
    // 목록 조회
    scwin.ins_Search();
};
scwin.btn_delete_onclick = function() {
    // 삭제
    scwin.ins_Delete();
};
scwin.trs_Delete_OnFail = function() {
    alert_tr_error(trs_Delete);
};
scwin.trs_Delete_OnSuccess = function() {
    //alert( getMessageParam("MSG-A001", "삭제") );
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_Search();
};
scwin.btn_ret_onclick = function() {
    // 반송처리
    scwin.ins_Ret();
};
scwin.trs_Ret_OnFail = function() {
    alert_tr_error(trs_Ret);
};
scwin.trs_Ret_OnSuccess = function() {
    //alert( getMessageParam("MSG-A001", "삭제") );
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));

    // 재조회
    scwin.ins_Search();
};
scwin.grd_ApplInfo_OnDblClick = function(row, colid) {
    if (row == 0) return;
    if (colid == "ISU_NM") {
        var sStdCd = dts_ApplInfo.getCellData(row, "STD_CD");
        var sContnTpCd = dts_ApplInfo.getCellData(row, "STD_CD_APPL_CONTN_TP_CD"); // 상품구분
        var sContnTpCdTemp = dts_ApplInfo.getCellData(row, "STD_CD_APPL_CONTN_TP_CD_TEMP");
        var sKnd = "";
        if (sContnTpCd == "02") {
            sKnd = "주권";
        } else if (sContnTpCd == "10") {
            sKnd = "주식워런트";
        } else if (sContnTpCd == "11") {
            sKnd = "ELS_DLS";
        } else if (sContnTpCd == "12") {
            sKnd = "ETN";
        } else if (sContnTpCd == "77") {
            sKnd = "전자단기사채";
        }
        if (sContnTpCd == "08") {
            txb_param1.setValue(dts_ApplInfo.getCellData(row, "STD_CD"));
        } else {
            txb_param1.setValue(dts_ApplInfo.getCellData(row, "STD_CD"));
        }
        if (txb_param1.getValue() == "") {
            $c.win.alert("삭제처리완료된 상품의 상세화면은 조회>표준코드삭제내역 에서 확인하세요.");
            return;
        }
        fn_GetPar = fn_GetParam;
        ins_ViewIsuMaster(sKnd, sStdCd);
    }
};
scwin.txb_ISU_NM_onkeyup = function() {
    fn_DelChar(this);
    if (txb_ISU_NM.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_Search();
        } else {

        }
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    fn_DelChar(this);
    if (txb_ISUR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_Search();
        } else {

        }
    }
};
scwin.cmb_STD_CD_APPL_CONTN_TP_CD_OnSelChange = function() {
    scwin.ins_Search();
};
scwin.cmb_APPL_PROCS_TP_CD_OnSelChange = function() {
    scwin.ins_Search();
};
scwin.img_BND_CLSS_CD_ERASER_onclick = function() {
    txb_ISUR_CD.setValue("");
    txb_ISUR_NM.setValue("");
};
